// Provision subscriber imsi-208930000000001 into the free5gc MongoDB database.
// Documents mirror the structure written by free5gc webconsole / docker/free5gc/free5gc-dbpython/add_subscribers.py
// (ueId keeps the "imsi-" prefix; integers are stored as int32).
// K (permanentKey) and OPc match the UERANSIM UE config in charts/ueransim/values.yaml.
const db = db.getSiblingDB('free5gc');
const ueId = 'imsi-208930000000001';
const plmn = '20893';
const sst = NumberInt(1);
const sd = '010203';

// idempotent: remove any previous copy of this subscriber
const colls = [
  'subscriptionData.provisionedData.smfSelectionSubscriptionData',
  'subscriptionData.provisionedData.smData',
  'policyData.ues.smData',
  'policyData.ues.amData',
  'subscriptionData.provisionedData.amData',
  'subscriptionData.authenticationData.authenticationSubscription',
];
colls.forEach(c => db.getCollection(c).deleteMany({ ueId: ueId }));

db.getCollection('subscriptionData.authenticationData.authenticationSubscription').insertOne({
  ueId: ueId,
  servingPlmnId: plmn,
  authenticationMethod: '5G_AKA',
  authenticationManagementField: '8000',
  permanentKey: { permanentKeyValue: '8baf473f2f8fd09487cccbd7097c6862', encryptionKey: 0, encryptionAlgorithm: 0 },
  opc: { opcValue: '8e27b6af0e692e750f32667a3b14605d', encryptionKey: 0, encryptionAlgorithm: 0 },
  milenage: { op: { opValue: '', encryptionKey: 0, encryptionAlgorithm: 0 } },
  sequenceNumber: '16f3b3f70fc2',
});

db.getCollection('subscriptionData.provisionedData.amData').insertOne({
  ueId: ueId,
  servingPlmnId: plmn,
  gpsis: ['msisdn-0900000001'],
  nssai: { defaultSingleNssais: [{ sst: sst, sd: sd }], singleNssais: [{ sst: sst, sd: sd }] },
  subscribedUeAmbr: { downlink: '2 Gbps', uplink: '1 Gbps' },
});

db.getCollection('subscriptionData.provisionedData.smfSelectionSubscriptionData').insertOne({
  ueId: ueId,
  servingPlmnId: plmn,
  subscribedSnssaiInfos: { '01010203': { dnnInfos: [{ dnn: 'internet' }] } },
});

db.getCollection('subscriptionData.provisionedData.smData').insertOne({
  ueId: ueId,
  servingPlmnId: plmn,
  singleNssai: { sst: sst, sd: sd },
