    internet: {
      pduSessionTypes: { defaultSessionType: 'IPV4', allowedSessionTypes: ['IPV4'] },
      sscModes: { defaultSscMode: 'SSC_MODE_1', allowedSscModes: ['SSC_MODE_2', 'SSC_MODE_3'] },
      sessionAmbr: { uplink: '200 Mbps', downlink: '100 Mbps' },
      '5gQosProfile': {
        '5qi': NumberInt(9),
        arp: { priorityLevel: NumberInt(8), preemptCap: 'NOT_PREEMPT', preemptVuln: 'NOT_PREEMPTABLE' },
        priorityLevel: NumberInt(8),
      },
    },
  },
});

db.getCollection('policyData.ues.amData').insertOne({
  ueId: ueId,
  subscCats: ['free5gc'],
});

db.getCollection('policyData.ues.smData').insertOne({
  ueId: ueId,
  smPolicySnssaiData: {
    '01010203': { snssai: { sst: sst, sd: sd }, smPolicyDnnData: { internet: { dnn: 'internet' } } },
  },
});

colls.forEach(c => print(c + ': ' + db.getCollection(c).countDocuments({ ueId: ueId })));

